export async function readChatFile(file: File): Promise<{ text: string; title: string }> {
  const base = file.name.replace(/\.(txt|zip)$/i, "");
  const title = base.replace(/^WhatsApp Chat (with|-) /i, "").trim() || "Chat";
  if (/\.zip$/i.test(file.name)) {
